        runtime
            .with_owner(root, |runtime| {
                runtime.dispose_any(root)?;
                assert_eq!(
                    runtime.on_cleanup(|_| panic!("dead owner")),
                    Err(RuntimeError::OwnerDisposed)
                );
                Ok(())
            })
            .unwrap();
        assert_eq!(runtime.status(), RuntimeStatus::Healthy);
