mod scheduling {
    use super::*;
    fn setup() -> (Runtime, OwnerHandle, Signal<i32>) {
        let (r, o) = pair();
        let s = signal(&r, o, 0);
        (r, o, s)
    }
    fn install(rt: &Runtime) -> Rc<Cell<usize>> {
        let n = Rc::new(Cell::new(0));
        let c = n.clone();
        rt.install_hook(move |_| c.set(c.get() + 1)).unwrap();
        n
    }
    #[test]
    fn installation_and_writes_coalesce_until_flush_consumes_request() {
        let (runtime, root, input) = setup();
        let calls = install(&runtime);
        assert_eq!(calls.get(), 0);
        input.try_set(&runtime, 1).unwrap();
        assert_eq!(calls.get(), 0); // No effect work.
        observe(&runtime, root, input);
        assert_eq!(calls.get(), 1);
        for value in 2..100 {
            input.try_set(&runtime, value).unwrap();
        }
        assert_eq!(calls.get(), 1);
        runtime.flush_with(Default::default()).unwrap();
        assert!(!runtime.flush_notification_outstanding());
        input.try_set(&runtime, 100).unwrap();
        assert_eq!(calls.get(), 2);
        runtime.flush_with(Default::default()).unwrap();
        input.try_set(&runtime, 100).unwrap();
        assert_eq!(calls.get(), 2); // Equality cut.
    }
    #[test]
    fn batch_error_is_not_a_transaction_and_still_notifies_without_poison() {
        let (runtime, root, input) = setup();
        observe(&runtime, root, input);
        runtime.flush_with(Default::default()).unwrap();
        let calls = install(&runtime);
        let result: Result<(), _> = runtime.batch(|runtime| {
            input.try_set(runtime, 5)?;
            Err(RuntimeError::CallbackFailed("host"))
        });
        assert_eq!(result, Err(RuntimeError::CallbackFailed("host")));
        assert_eq!(input.try_peek_copy(&runtime).unwrap(), 5);
        assert_eq!(runtime.status(), RuntimeStatus::Healthy);
        assert_eq!(calls.get(), 1);
    }
    #[test]
    fn hook_rejects_all_reactive_mutation_and_synchronous_flush_without_consuming_flag() {
        let (runtime, root, input) = setup();
        let (other, _, external) = setup();
        let weak = other.downgrade();
        runtime
            .install_hook(move |runtime| {
                assert_eq!(input.try_get_copy(runtime), Err(RuntimeError::Reentrancy));
                assert_eq!(input.try_set(runtime, 2), Err(RuntimeError::Reentrancy));
                assert_eq!(runtime.effect(|_| Ok(())), Err(RuntimeError::Reentrancy));
                assert_eq!(runtime.dispose_any(root), Err(RuntimeError::Reentrancy));
                assert_eq!(
                    runtime.flush_with(Default::default()).unwrap_err(),
                    RuntimeError::Reentrancy
                );
                assert_eq!(
                    runtime.clear_request_flush_hook(),
                    Err(RuntimeError::Reentrancy)
                );
                assert_eq!(runtime.install_hook(|_| ()), Err(RuntimeError::Reentrancy));
                assert_eq!(
                    runtime.rearm_flush_notification(),
                    Err(RuntimeError::Reentrancy)
                );
                assert_eq!(runtime.batch(|_| Ok(())), Err(RuntimeError::Reentrancy));
                let other = weak.upgrade().unwrap();
                assert_eq!(external.try_set(&other, 2), Err(RuntimeError::Reentrancy));
                assert_eq!(
                    other.flush_with(Default::default()).unwrap_err(),
                    RuntimeError::Reentrancy
                );
                assert!(runtime.flush_notification_outstanding());
            })
            .unwrap();
        observe(&runtime, root, input);
        assert_eq!(runtime.status(), RuntimeStatus::Healthy);
        assert_eq!(other.status(), RuntimeStatus::Healthy);
        assert_eq!(input.try_peek_copy(&runtime).unwrap(), 0);
        runtime.flush_with(Default::default()).unwrap();
    }
    #[test]
    fn replacement_removal_and_rearm_preserve_work_and_host_responsibility() {
        let (runtime, root, input) = setup();
        observe(&runtime, root, input);
        let old = install(&runtime);
        assert_eq!(old.get(), 1);
        let new = install(&runtime);
        assert_eq!((old.get(), new.get()), (1, 1));
        runtime.rearm_flush_notification().unwrap();
        assert_eq!(new.get(), 2);
        runtime.clear_request_flush_hook().unwrap();
        assert!(!runtime.flush_notification_outstanding());
        assert!(runtime.has_pending_effects());
        runtime.rearm_flush_notification().unwrap();
        assert!(!runtime.flush_notification_outstanding());
        let last = install(&runtime);
        assert_eq!(last.get(), 1);
        runtime.flush_with(Default::default()).unwrap();
        runtime.rearm_flush_notification().unwrap();
        assert_eq!(last.get(), 1);
    }
    #[test]
    fn yielded_and_round_limited_flush_rearm_only_after_restoring_contexts() {
        let (runtime, root, input) = setup();
        let calls = install(&runtime);
        runtime
            .with_owner(root, |runtime| {
                runtime.effect(move |runtime| {
                    assert!(!runtime.flush_notification_outstanding());
                    let value = input.try_get_copy(runtime)?;
                    input.try_set(runtime, value + 1)?;
                    Ok(())
                })
            })
            .unwrap();
        assert_eq!(calls.get(), 1);
        let report = runtime
            .flush_with(FlushOptions {
                max_rounds: 2,
                ..Default::default()
            })
            .unwrap();
        assert_eq!(report.outcome, FlushOutcome::RoundLimit);
        assert_eq!(calls.get(), 2);
        let report = runtime
            .flush_with(FlushOptions {
                max_work: Some(0),
                ..Default::default()
            })
            .unwrap();
        assert_eq!(report.outcome, FlushOutcome::Yielded);
        assert_eq!(calls.get(), 3);
        runtime.shutdown().unwrap();
        assert!(!runtime.flush_notification_outstanding());
        assert_eq!(calls.get(), 3);
    }
    #[test]
    fn cleanup_writes_notify_after_disposal_guards_restore_and_dead_work_is_ignored() {
        let (runtime, root, input) = setup();
        observe(&runtime, root, input);
        runtime.flush_with(Default::default()).unwrap();
        let calls = install(&runtime);
        let doomed = runtime.create_root().unwrap();
        runtime
            .with_owner(doomed, |runtime| {
                runtime.on_cleanup(move |runtime| {
                    input.try_set(runtime, 5)?;
                    Ok(())
                })
            })
            .unwrap();
        runtime.dispose_any(doomed).unwrap();
        assert_eq!(calls.get(), 1);
        runtime.dispose_any(root).unwrap();
        runtime.rearm_flush_notification().unwrap();
        assert_eq!(calls.get(), 1);
        assert!(!runtime.has_pending_effects());
        assert!(!runtime.flush_notification_outstanding());
    }
    #[test]
    fn update_notification_waits_for_the_entire_outer_operation() {
        let (runtime, root, input) = setup();
        observe(&runtime, root, input);
        runtime.flush_with(Default::default()).unwrap();
        let calls = install(&runtime);
        let result = input.try_update_cloned(&runtime, |_| {
            input.try_set(&runtime, 3).unwrap();
            assert_eq!(calls.get(), 0);
        });
        assert_eq!(result, Err(RuntimeError::UpdateConflict));
        assert_eq!(calls.get(), 1);
    }
    #[test]
    fn notifications_are_scheduler_requests_not_window_or_graphics_work() {
        let (runtime, root, input) = setup();
        let events = Rc::new(RefCell::new(Vec::new()));
        let captured = events.clone();
        runtime
            .install_hook(move |_| captured.borrow_mut().push("flush requested"))
            .unwrap();
        observe(&runtime, root, input);
        assert_eq!(*events.borrow(), ["flush requested"]);
        // The host handles the event later, after the hook returns.
        assert_eq!(
            runtime.flush_with(Default::default()).unwrap().outcome,
            FlushOutcome::Stabilized
        );
        assert!(!runtime.has_pending_effects());
    }
    #[test]
    fn deferred_foreign_runtime_work_can_notify_at_a_host_lazy_evaluation_exit() {
        let (runtime, root, input) = setup();
        let memo = runtime
            .with_owner(root, |runtime| {
                runtime.memo(move |runtime| input.try_get_copy(runtime))
            })
            .unwrap();
        memo.try_get_copy(&runtime).unwrap();
        let calls = install(&runtime);
        let (other, other_root, _) = setup();
        let weak = runtime.downgrade();
        other
            .with_owner(other_root, |other| {
                other.effect(move |_| {
                    let runtime = weak.upgrade().unwrap();
                    input.try_set(&runtime, 1)?;
                    runtime.with_owner(root, |runtime| runtime.effect(|_| Ok(())))?;
                    Ok(())
                })
            })
            .unwrap();
        other.flush_with(Default::default()).unwrap();
        // No global runtime registry: callbacks never synchronously notify a
        // foreign runtime under the outer thread's restricted capabilities.
        assert_eq!(calls.get(), 0);
        assert_eq!(memo.try_peek_copy(&runtime).unwrap(), 1);
        assert_eq!(calls.get(), 1);
        runtime.flush_with(Default::default()).unwrap();
    }
    #[test]
    fn final_facade_drops_hook_captures_under_destructor_guard_without_invoking_it() {
        struct Capture(Runtime, Rc<Cell<usize>>);
        impl Drop for Capture {
            fn drop(&mut self) {
                assert_eq!(self.0.create_root(), Err(RuntimeError::Reentrancy));
                self.1.set(self.1.get() + 1);
            }
        }
        let (runtime, _, _) = setup();
        let (other, _, _) = setup();
        let drops = Rc::new(Cell::new(0));
        let capture = Capture(other.clone(), drops.clone());
        runtime
            .install_hook(move |_| {
                let _capture = &capture;
                panic!("not an implicit final flush");
            })
            .unwrap();
        drop(runtime);
        assert_eq!(drops.get(), 1);
        assert_eq!(other.status(), RuntimeStatus::Healthy);
    }
}

mod signals {
    use super::*;
    fn setup<T: PartialEq + 'static>(v: T) -> (Runtime, OwnerHandle, Signal<T>) {
        let (r, o) = pair();
        let s = signal(&r, o, v);
        (r, o, s)
    }
    #[test]
    fn creation_requires_explicit_live_owner() {
        let runtime = Runtime::new();
        assert_eq!(runtime.signal(1), Err(RuntimeError::MissingOwner));
        assert_eq!(
            runtime.signal_with(1, |_, _| false),
            Err(RuntimeError::MissingOwner)
        );
        assert_eq!(runtime.node_count(), 0);
        let root = runtime.create_root().unwrap();
        runtime
            .with_owner(root, |runtime| {
                runtime.dispose_any(root)?;
                assert_eq!(runtime.signal(1), Err(RuntimeError::OwnerDisposed));
                Ok(())
            })
            .unwrap();
        assert_eq!(runtime.status(), RuntimeStatus::Healthy);
    }
    #[test]
    fn cloned_values_survive_later_writes_and_disposal() {
        let (runtime, root, signal) = setup(String::from("initial"));
        let initial = signal.try_get_cloned(&runtime).unwrap();
        assert_eq!(initial, signal.try_peek_cloned(&runtime).unwrap());
        signal.try_set(&runtime, String::from("new")).unwrap();
        let current = signal.try_get_cloned(&runtime).unwrap();
        assert_eq!(current.as_str(), "new");
        assert_eq!(initial.as_str(), "initial");
        assert_ne!(initial, current);
        assert_eq!(revisions(&runtime, signal), (1, 1));
        runtime.dispose_any(root).unwrap();
        assert_eq!(current.as_str(), "new");
        assert_eq!(
            signal.try_get_cloned(&runtime),
            Err(RuntimeError::InvalidHandle)
        );
    }
    #[test]
    fn borrowed_reads_do_not_clone_but_clone_and_update_are_explicit() {
        struct Counted {
            value: u32,
            clones: Rc<Cell<usize>>,
        }
        impl Clone for Counted {
            fn clone(&self) -> Self {
                self.clones.set(self.clones.get() + 1);
                Self {
                    value: self.value,
                    clones: self.clones.clone(),
                }
            }
        }
        let runtime = Runtime::new();
        let root = runtime.create_root().unwrap();
        let clones = Rc::new(Cell::new(0));
        let signal = runtime
            .with_owner(root, |runtime| {
                runtime.signal_with(
                    Counted {
                        value: 1,
                        clones: clones.clone(),
                    },
                    |left, right| left.value == right.value,
                )
            })
            .unwrap();
        let previous = signal.try_with(&runtime, |value| value.value).unwrap();
        signal.try_peek_with(&runtime, |_| ()).unwrap();
        signal.try_with(&runtime, |_| ()).unwrap();
        assert_eq!(clones.get(), 0);
        signal
            .try_update_cloned(&runtime, |value| value.value += 1)
            .unwrap();
        assert_eq!(clones.get(), 1);
        assert_eq!(signal.try_with(&runtime, |value| value.value).unwrap(), 2);
        assert_eq!(previous, 1);
        assert_eq!(signal.try_get_cloned(&runtime).unwrap().value, 2);
        assert_eq!(clones.get(), 2);
    }
    #[test]
    fn non_clone_non_partial_eq_values_support_explicit_policy_and_identity() {
        struct Document {
            revision: u64,
            points: Vec<u32>,
        }
        let runtime = Runtime::new();
        let root = runtime.create_root().unwrap();
        let signal = runtime
            .with_owner(root, |runtime| {
                runtime.signal_with(
                    Document {
                        revision: 0,
                        points: vec![1, 2],
                    },
                    |left, right| left.revision == right.revision,
                )
            })
            .unwrap();
        signal
            .try_set(
                &runtime,
                Document {
                    revision: 1,
                    points: vec![3, 4],
                },
            )
            .unwrap();
        assert!(
            signal
                .try_with(&runtime, |value| value.points == [3, 4])
                .unwrap()
        );
        assert_eq!(revisions(&runtime, signal), (1, 1));

        let document = Rc::new(Document {
            revision: 0,
            points: vec![],
        });
        let identity = runtime
            .with_owner(root, |runtime| {
                runtime.signal_with(document.clone(), Rc::ptr_eq)
            })
            .unwrap();
        let initial = identity.try_get_cloned(&runtime).unwrap();
        identity.try_set(&runtime, document).unwrap();
        assert!(Rc::ptr_eq(
            &initial,
            &identity.try_get_cloned(&runtime).unwrap()
        ));
        identity
            .try_set(
                &runtime,
                Rc::new(Document {
                    revision: 0,
                    points: vec![],
                }),
            )
            .unwrap();
        assert_eq!(revisions(&runtime, identity), (1, 1));
    }
    #[test]
    fn float_policies_are_explicit_nan_signed_zero_and_tolerance() {
        let (runtime, root, nan) = setup(f64::NAN);
        nan.try_set(&runtime, f64::NAN).unwrap();
        assert_eq!(revisions(&runtime, nan), (1, 1));
        let zero = runtime
            .with_owner(root, |runtime| runtime.signal(0.0_f64))
            .unwrap();
        zero.try_set(&runtime, -0.0).unwrap();
        assert_eq!(revisions(&runtime, zero), (0, 0));
        assert_eq!(
            zero.try_get_copy(&runtime).unwrap().to_bits(),
            0.0_f64.to_bits()
        );

        let bits = runtime
            .with_owner(root, |runtime| {
                runtime.signal_with(f64::NAN, |left, right| left.to_bits() == right.to_bits())
            })
            .unwrap();
        bits.try_set(&runtime, f64::NAN).unwrap();
        assert_eq!(revisions(&runtime, bits), (0, 0));
        bits.try_set(&runtime, 0.0).unwrap();
        bits.try_set(&runtime, -0.0).unwrap();
        assert_eq!(revisions(&runtime, bits), (2, 2));

        let tolerance = runtime
            .with_owner(root, |runtime| {
                runtime.signal_with(1.0_f64, |left, right| (left - right).abs() < 0.1)
            })
            .unwrap();
        tolerance.try_set(&runtime, 1.05).unwrap();
        assert_eq!(tolerance.try_get_copy(&runtime).unwrap(), 1.0);
        let exact = runtime
            .with_owner(root, |runtime| runtime.signal(1.0_f64))
            .unwrap();
        exact.try_set(&runtime, 1.05).unwrap();
        assert_eq!(exact.try_get_copy(&runtime).unwrap(), 1.05);
    }
    #[test]
    fn wrong_runtime_and_disposed_handles_reject_all_access_without_callbacks() {
        let (runtime, root, signal) = setup(1_u32);
        let other = Runtime::new();
        assert_eq!(signal.try_get_copy(&other), Err(RuntimeError::WrongRuntime));
        assert_eq!(
            signal.try_peek_copy(&other),
            Err(RuntimeError::WrongRuntime)
        );
        assert_eq!(signal.try_set(&other, 2), Err(RuntimeError::WrongRuntime));
        assert_eq!(
            signal.try_update_cloned(&other, |_| panic!("must not run")),
            Err(RuntimeError::WrongRuntime)
        );
        runtime.dispose_any(root).unwrap();
        let new_root = runtime.create_root().unwrap();
        let new = runtime
            .with_owner(new_root, |runtime| runtime.signal(9_u32))
            .unwrap();
        assert_eq!(signal.key.index, new.key.index);
        assert_eq!(
            signal.try_get_copy(&runtime),
            Err(RuntimeError::InvalidHandle)
        );
        assert_eq!(
            signal.try_peek_copy(&runtime),
            Err(RuntimeError::InvalidHandle)
        );
        assert_eq!(
            signal.try_set(&runtime, 2),
            Err(RuntimeError::InvalidHandle)
        );
        assert_eq!(
            signal.try_update_cloned(&runtime, |_| panic!("must not run")),
            Err(RuntimeError::InvalidHandle)
        );
        assert_eq!(new.try_get_copy(&runtime).unwrap(), 9);
        assert_eq!(other.status(), RuntimeStatus::Healthy);
        assert_eq!(runtime.status(), RuntimeStatus::Healthy);
    }
    #[test]
    fn update_works_with_equality_cut_and_reentrant_equal_write_is_not_a_conflict() {
        let (runtime, _, signal) = setup(7_u32);
        let snapshot = signal.try_get_copy(&runtime).unwrap();
        signal.try_update_cloned(&runtime, |_| {}).unwrap();
        assert_eq!(snapshot, signal.try_get_copy(&runtime).unwrap());
        signal
            .try_update_cloned(&runtime, |value| {
                signal.try_set(&runtime, 7).unwrap();
                *value += 1;
            })
            .unwrap();
        assert_eq!(signal.try_get_copy(&runtime).unwrap(), 8);
        assert_eq!(revisions(&runtime, signal), (1, 1));
    }
    #[test]
    fn update_conflict_does_not_overwrite_retry_or_compare_stale_candidate() {
        let runtime = Runtime::new();
        let root = runtime.create_root().unwrap();
        let comparisons = Rc::new(Cell::new(0));
        let calls = comparisons.clone();
        let signal = runtime
            .with_owner(root, |runtime| {
                runtime.signal_with(0_u32, move |a, b| {
                    calls.set(calls.get() + 1);
                    a == b
                })
            })
            .unwrap();
        let callbacks = Cell::new(0);
        let result = signal.try_update_cloned(&runtime, |value| {
            callbacks.set(callbacks.get() + 1);
            signal.try_set(&runtime, 10).unwrap();
            *value = 1;
        });
        assert_eq!(result, Err(RuntimeError::UpdateConflict));
        assert_eq!(signal.try_get_copy(&runtime).unwrap(), 10);
        assert_eq!(callbacks.get(), 1);
        assert_eq!(comparisons.get(), 1); // Only the nested set was compared.
        assert_eq!(runtime.status(), RuntimeStatus::Healthy);
    }
    #[test]
    fn update_detects_change_back_to_initial_value_by_revision_not_value() {
        let (runtime, _, signal) = setup(0_u32);
        let result = signal.try_update_cloned(&runtime, |value| {
            signal.try_set(&runtime, 1).unwrap();
            signal.try_set(&runtime, 0).unwrap();
            *value = 2;
        });
        assert_eq!(result, Err(RuntimeError::UpdateConflict));
        assert_eq!(signal.try_get_copy(&runtime).unwrap(), 0);
        assert_eq!(revisions(&runtime, signal), (2, 2));
    }
    #[test]
    fn update_disposal_and_reuse_cannot_commit_to_the_new_occupant() {
        let (runtime, root, signal) = setup(1_u32);
        let replacement = Cell::new(None);
        let result = signal.try_update_cloned(&runtime, |value| {
            runtime.dispose_any(root).unwrap();
            let new_root = runtime.create_root().unwrap();
            let new = runtime
                .with_owner(new_root, |runtime| runtime.signal(9_u32))
                .unwrap();
            replacement.set(Some(new));
            *value = 2;
        });
        assert_eq!(result, Err(RuntimeError::InvalidHandle));
        let new = replacement.get().unwrap();
        assert_eq!(signal.key.index, new.key.index);
        assert_eq!(new.try_get_copy(&runtime).unwrap(), 9);
    }
    #[test]
    fn poisoned_or_closed_runtime_rejects_reads_and_writes_before_user_callbacks() {
        let (runtime, _, signal) = setup(1_u32);
        runtime.record_failure(RuntimeError::CallbackFailed("failure"));
        assert_eq!(signal.try_get_copy(&runtime), Err(RuntimeError::Poisoned));
        assert_eq!(signal.try_peek_copy(&runtime), Err(RuntimeError::Poisoned));
        assert_eq!(signal.try_set(&runtime, 2), Err(RuntimeError::Poisoned));
        assert_eq!(
            signal.try_update_cloned(&runtime, |_| panic!("must not run")),
            Err(RuntimeError::Poisoned)
        );
        let (closed, _, closed_signal) = setup(1_u32);
        closed.shutdown().unwrap();
        assert_eq!(
            closed_signal.try_peek_copy(&closed),
            Err(RuntimeError::RuntimeClosed)
        );
        assert_eq!(
            closed_signal.try_set(&closed, 2),
            Err(RuntimeError::RuntimeClosed)
        );
    }
}

mod verification {
    use super::*;
    #[test]
    fn verifies_dynamic_edges_queue_disposal_and_poison_teardown() {
        let rt = Runtime::new();
        let root = rt.create_root().unwrap();
        let (branch, a, b) = rt
            .with_owner(root, |rt| {
                Ok((rt.signal(true)?, rt.signal(1)?, rt.signal(2)?))
            })
            .unwrap();
        let memo = rt
            .with_owner(root, |rt| {
                rt.memo(move |rt| {
                    if branch.try_get_copy(rt)? {
                        Ok(a.try_get_copy(rt)?)
                    } else {
                        Ok(b.try_get_copy(rt)?)
                    }
                })
            })
            .unwrap();
        rt.with_owner(root, |rt| {
            rt.effect(move |rt| {
                memo.try_get_copy(rt)?;
                Ok(())
            })
        })
        .unwrap();
        for i in 0..100 {
            rt.verify_invariants().unwrap();
            branch.try_set(&rt, i % 2 == 0).unwrap();
            a.try_set(&rt, i).unwrap();
            b.try_set(&rt, i + 1).unwrap();
            rt.verify_invariants().unwrap();
            rt.flush_with(Default::default()).unwrap();
            rt.verify_invariants().unwrap();
        }
        let effect = rt
            .with_owner(root, |rt| {
                rt.effect(|_| Err(RuntimeError::CallbackFailed("test")))
            })
            .unwrap();
        rt.flush_with(Default::default()).unwrap();
        rt.verify_invariants().unwrap();
        rt.dispose_any(effect).unwrap();
        rt.verify_invariants().unwrap();
        rt.shutdown().unwrap();
        rt.verify_invariants().unwrap();
    }
}

mod runtime {
    use super::*;
    #[test]
    fn independent_runtimes_have_distinct_identity_and_same_slot_is_not_enough() {
        let a = Runtime::new();
        let b = Runtime::new();
        let owner_a = a.create_root().unwrap();
        let owner_b = b.create_root().unwrap();
        assert_eq!(owner_a.key, owner_b.key);
        assert_ne!(owner_a.runtime, owner_b.runtime);
        assert_eq!(owner_a.validate(&b), Err(RuntimeError::WrongRuntime));
        assert_eq!(b.create_owner(owner_a), Err(RuntimeError::WrongRuntime));
        assert_eq!(b.dispose_any(owner_a), Err(RuntimeError::WrongRuntime));
        assert_eq!(a.owner_count(), 1);
        assert_eq!(b.owner_count(), 1);
        let signal = stored_signal(&a, owner_a, 7_u32);
        assert_eq!(signal.validate(&b), Err(RuntimeError::WrongRuntime));
        assert_eq!(b.status(), RuntimeStatus::Healthy);
    }
    #[test]
    fn cloning_facade_shares_storage_but_copying_handles_does_not_own_nodes() {
        let runtime = Runtime::new();
        let cloned = runtime.clone();
        let root = runtime.create_root().unwrap();
        let handle = stored_signal(&runtime, root, 7_u32);
        let copy = handle;
        assert_eq!(copy, handle);
        drop(runtime);
        assert_eq!(copy.validate(&cloned), Ok(()));
        assert_eq!(cloned.dispose_any(root), Ok(DisposeOutcome::Disposed));
        assert_eq!(copy.validate(&cloned), Err(RuntimeError::InvalidHandle));
    }
    #[test]
    fn weak_facade_does_not_extend_runtime_lifetime() {
        let weak = {
            let runtime = Runtime::new();
            let weak = runtime.downgrade();
            assert!(weak.upgrade().is_some());
            weak
        };
        assert!(weak.upgrade().is_none());
    }
    #[test]
    fn subtree_disposal_is_idempotent_and_preserves_other_roots() {
        let runtime = Runtime::new();
        let root = runtime.create_root().unwrap();
        let child = runtime.create_owner(root).unwrap();
        let grandchild = runtime.create_owner(child).unwrap();
        let sibling = runtime.create_owner(root).unwrap();
        let other_root = runtime.create_root().unwrap();
        let root_signal = stored_signal(&runtime, root, 1_u32);
        let child_signal = stored_signal(&runtime, child, 2_u32);
        let grandchild_signal = stored_signal(&runtime, grandchild, 3_u32);
        let sibling_signal = stored_signal(&runtime, sibling, 4_u32);
        assert_eq!(runtime.dispose_any(child), Ok(DisposeOutcome::Disposed));
        assert_eq!(
            runtime.dispose_any(child),
            Ok(DisposeOutcome::AlreadyDisposed)
        );
        assert_eq!(
            child_signal.validate(&runtime),
            Err(RuntimeError::InvalidHandle)
        );
        assert_eq!(
            grandchild_signal.validate(&runtime),
            Err(RuntimeError::InvalidHandle)
        );
        assert_eq!(root_signal.validate(&runtime), Ok(()));
        assert_eq!(sibling_signal.validate(&runtime), Ok(()));
        assert_eq!(other_root.validate(&runtime), Ok(()));
        assert_eq!(runtime.owner_count(), 3);
        assert_eq!(runtime.node_count(), 2);
        // Sibling's parent back-index was repaired by swap_remove.
        runtime.dispose_any(sibling).unwrap();
        runtime.dispose_any(root).unwrap();
        assert_eq!(runtime.owner_count(), 1);
        assert_eq!(runtime.node_count(), 0);
        assert_eq!(other_root.validate(&runtime), Ok(()));
    }
    #[test]
    fn effect_disposal_repairs_owner_node_back_index() {
        let runtime = Runtime::new();
        let root = runtime.create_root().unwrap();
        let first = stored_effect(&runtime, root);
        let second = stored_effect(&runtime, root);
        let third = stored_effect(&runtime, root);
        runtime.dispose_any(first).unwrap();
        runtime.dispose_any(third).unwrap();
        assert_eq!(second.validate(&runtime), Ok(()));
        assert_eq!(
            runtime.dispose_any(first),
            Ok(DisposeOutcome::AlreadyDisposed)
        );
        runtime.dispose_any(root).unwrap();
        assert_eq!(runtime.node_count(), 0);
    }
    #[test]
    fn shutdown_closes_all_roots_and_is_idempotent() {
        let runtime = Runtime::new();
        let first = runtime.create_root().unwrap();
        let second = runtime.create_root().unwrap();
        stored_signal(&runtime, first, 1_u32);
        stored_memo(&runtime, second);
        runtime.shutdown().unwrap();
        runtime.shutdown().unwrap();
        assert_eq!(runtime.node_count(), 0);
        assert_eq!(runtime.owner_count(), 0);
        assert_eq!(runtime.status(), RuntimeStatus::Closed);
        assert_eq!(runtime.create_root(), Err(RuntimeError::RuntimeClosed));
        assert_eq!(first.validate(&runtime), Err(RuntimeError::RuntimeClosed));
        assert_eq!(
            runtime.dispose_any(first),
            Ok(DisposeOutcome::AlreadyDisposed)
        );
    }
    #[test]
    fn deep_owner_tree_disposal_is_iterative() {
        let runtime = Runtime::new();
        let root = runtime.create_root().unwrap();
        let mut owner = root;
        for _ in 0..10_000 {
            owner = runtime.create_owner(owner).unwrap();
        }
        assert_eq!(runtime.owner_depth(owner), Ok(10_000));
        runtime.dispose_any(root).unwrap();
        assert_eq!(runtime.owner_count(), 0);
    }
}
